  async function saveReport(e){
    e.preventDefault();
    const f=new FormData(e.target), group=String(f.get("ministry_group")||"");
    const teachersTrained=group==="Teaching Ministry"?(+f.get("teachers_trained")||0):0;
    const teachersInvolved=group==="Teaching Ministry"?(+f.get("teachers_involved")||0):0;
    const peopleReached=(group==="CEF Promotion"||group==="Prayer Meetings")?(+f.get("people_reached")||0):0;
    const peopleInvolved=(group==="CEF Promotion"||group==="Prayer Meetings")?(+f.get("people_involved")||0):0;
    if(teachersInvolved>teachersTrained){toast("People involved in CEF ministry cannot be greater than people trained.",false);return}
    if(peopleInvolved>peopleReached){toast("People involved in CEF ministry cannot be greater than people reached.",false);return}
    const obj={staff_auth_user_id:state.user.id,report_date:f.get("report_date"),ministry_group:group,ministry_type:f.get("ministry_type"),location:f.get("location"),activity_count:+f.get("activity_count")||0,
      children_reached:(group==="Teaching Ministry"||group==="CEF Promotion"||group==="Prayer Meetings")?0:(+f.get("children_reached")||0),
      decisions_for_christ:(group==="Teaching Ministry"||group==="CEF Promotion"||group==="Prayer Meetings")?0:(+f.get("decisions_for_christ")||0),
      children_attending_church:(group==="Teaching Ministry"||group==="CEF Promotion"||group==="Prayer Meetings")?0:(+f.get("children_attending_church")||0),
      teachers_trained:teachersTrained,teachers_involved:teachersInvolved,people_reached:peopleReached,people_involved:peopleInvolved,
      prayer_meetings:group==="Prayer Meetings"?(+f.get("activity_count")||0):0,gnc_classes:group==="GNC"?(+f.get("activity_count")||0):0,cef_promotions:group==="CEF Promotion"?(+f.get("activity_count")||0):(+f.get("cef_promotions")||0),notes:f.get("notes")};
    const {error}=await supabase.from("ministry_reports").insert(obj);if(error){toast(authError(error),false);return}
    toast("Ministry report saved successfully.");await loadStaffData();state.lockedReportGroup=null;state.page="dashboard";render()
  }
