  async function reviewApplication(id,status){const a=state.applications.find(x=>x.id===id);if(!a)return;const notes=prompt(status==="approved"?"Optional approval note:":"Reason for rejection:");if(status==="rejected"&&!notes){toast("Please provide a rejection reason.",false);return}const {error}=await supabase.from("staff_registration_requests").update({status,national_director_notes:notes||null,reviewed_by:state.user.id,reviewed_at:new Date().toISOString()}).eq("id",id);if(error){toast("Approval failed: "+authError(error),false);return}const message=status==="approved"?"Your CEF Pakistan staff application has been approved by the National Director."+(notes?" Note: "+notes:""):"Your staff application was rejected by the National Director."+(notes?" Reason: "+notes:"");await supabase.from("staff_notifications").insert({recipient_auth_user_id:a.auth_user_id,title:status==="approved"?"Staff Application Approved":"Staff Application Rejected",message,category:"Application"});toast(status==="approved"?"Application approved and staff notified.":"Application rejected and staff notified.");await loadNDData();render()}
  async function reviewBudget(id,status,approvedAmount=null){const b=state.budgets.find(x=>x.id===id);if(!b)return;let amount=approvedAmount;if(status==="approved"&&amount===null){amount=Number(b.amount||0)}if(status==="approved"&&(!Number.isFinite(amount)||amount<0)){toast("Approved amount must be zero or greater.",false);return}if(status==="approved"&&amount>Number(b.amount||0)){toast("Approved amount cannot exceed the requested amount.",false);return}const notes=prompt(status==="approved"?`ND note (approved ₨ ${Number(amount).toLocaleString()}):`:"Reason for rejection:");if(status==="rejected"&&!notes)return;const payload={status,approved_amount:status==="approved"?amount:0,nd_notes:notes||null,reviewed_by:state.user.id,reviewed_at:new Date().toISOString()};const {error}=await supabase.from("staff_budget_applications").update(payload).eq("id",id);if(error){toast(authError(error),false);return}await supabase.from("staff_notifications").insert({recipient_auth_user_id:b.staff_auth_user_id,title:status==="approved"?"Budget Decision":"Budget Request Rejected",message:status==="approved"?`Your budget request "${b.title}" was approved for PKR ${Number(amount).toLocaleString()}.${notes?" ND note: "+notes:""}`:`Your budget request "${b.title}" was rejected.${notes?" Reason: "+notes:""}`,category:"Budget"});toast(status==="approved"?`Budget approved for ₨ ${Number(amount).toLocaleString()}.`:"Budget request rejected.");await loadNDData();render()}
  function viewApplication(id){const a=state.applications.find(x=>x.id===id);if(!a)return;openModal(`<h2>${esc(a.full_name)}</h2><p class="kpi-note">Complete staff application</p><div class="detail-grid">${Object.entries({ "Staff Registration No.":a.staff_reg_no,"Father Name":a.father_name,"City":a.city,"Region":a.region,"Country":a.country,"Phone":a.phone,"Email":a.email,"Designation":a.designation,"Date Joined":fmtDate(a.date_joined),"Status":a.status,"Created":fmtDate(a.created_at?.slice(0,10))}).map(([k,v])=>`<div class="detail"><small>${k}</small><b>${esc(v||"—")}</b></div>`).join("")}</div><div style="margin-top:18px"><b>Training</b><p>${a.cmi_completed?"✓ CMI completed":"CMI: —"} • ${a.cmi_weeks||0} weeks • ${a.tec_1_completed?"✓ TEC-1":""} ${a.tec_2_completed?"✓ TEC-2":""}</p></div>`)}
